pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzzed parameter: an arbitrary caller address that the fuzzer will pick.
    // General rule: owner() should always return the stored owner (deployer/address set in constructor), i.e. address(this)
    // The mutant returns msg.sender; thus for some caller addresses (when caller != stored owner) the mutant will return a different value.
    function testFuzz_property(address caller) public {
        // keep domain wide but avoid zero address as a mild assumption (still admissible if zero but not needed)
        // We do not bound caller to allow fuzzer to find any address different from deployer
        // Call owner() as the chosen caller; observe returned value via try/catch to be robust.

        bool ok;
        address reported;
        // perform external call to owner() as 'caller'
        vm.prank(caller);
        try c.owner() returns (address o) {
            ok = true;
            reported = o;
        } catch {
            ok = false;
            reported = address(0);
        }

        // The reference contract always returns the stored owner (the deployer passed in setUp: address(this) of the test contract at deployment time),
        // and the call completes (does not revert). So for all callers ok==true and reported == address(this) (the deployer used in constructor).
        // The mutant will for some caller (when caller != stored owner) return caller instead, making reported != address(this).
        assertTrue(ok && reported == address(this));
    }
}

