import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz newOwner; the reference contract requires newOwner != address(0) and thus
    // transferOwnership should revert (we observe as a failed call) when newOwner == address(0),
    // and should succeed for any other address. The mutant removed that check so calling with
    // address(0) will succeed there, breaking the invariant.
    function testFuzz_property(address newOwner) public {
        // keep domain wide; no restrictive assumes so fuzzer can hit zero address

        bool ok;
        // call transferOwnership and record whether it succeeded (did not revert)
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: ok must equal (newOwner != address(0))
