pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz the caller (must be owner) and an arbitrary address candidate for newOwner
    function testFuzz_property(address caller, address newOwner) public {
        // Keep domain wide but ensure caller is the current owner (so only owner can call)
        // setUp set owner to address(this). We fuzz 'caller' but we need the call to be from owner.
        // So constrain caller to be address(this) or else the call would revert due to onlyOwner and be unrelated.
        // We still fuzz newOwner freely (including address(0)).
        vm.assume(caller == address(this));

        bool ok;
        // perform the call as caller and observe whether it succeeds or reverts
        try c.transferOwnership{gas: gasleft()}(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: For the reference C, transferring ownership to address(0) MUST revert (fail).
        // Therefore we assert: if newOwner == address(0) then the transfer must have failed (ok == false).
        // This property holds for all inputs on the reference and is violated by the mutant that removed the check.
        if (newOwner == address(0)) {
            assertTrue(!ok);
        } else {
            // For non-zero newOwner the call should succeed; keep this as part of the natural invariant to ensure behavior is consistent
            assertTrue(ok);
        }
    }
}

