        // the observed revert and whether the current tx sender equals owner or rewardDistributor.
        // Perform the call (from this test contract's msg.sender) to record revert; the parameters use `caller` as new distributor.
        try c.setRewardDistributor(caller) { reverted = false; } catch { reverted = true; }

        // Determine whether this test's caller (msg.sender) is owner or rewardDistributor via public getters
        address who = msg.sender;
        address owner = c.owner();
        // rewardDistributor is a public variable so has a getter
