        // General rule: the call must revert if and only if the caller (this test's msg.sender) is neither owner nor current distributor.
        // That is, if msg.sender == owner || msg.sender == distributor then reverted == false, else reverted == true.
        assert(((who == owner) || (who == distributor)) == (!reverted));
    }
    receive() external payable { }
}

