pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzzed parameter: actor address who will attempt to call setRewardDistributor
    // General rule: onlyOwner can change rewardDistributor; test asserts that when a non-owner (fuzzed) calls
    // setRewardDistributor, the call does NOT succeed (i.e., rewardDistributor remains owner) for the reference.
    // The mutant that requires msg.sender == rewardDistributor instead will allow the current rewardDistributor
    // (which is initially owner) or other addresses to change it in ways that can differ; the fuzzer can find
    // an address that when used as caller produces a differing rewardDistributor after calling addReward and
    // then setRewardDistributor on the mutant. We therefore fuzz an arbitrary address 'actor' and ensure
    // that a non-owner actor cannot change rewardDistributor on the reference.
    function testFuzz_property(address actor) public {
        // keep actor wide but non-zero to be meaningful
        vm.assume(actor != address(0));

        // initial rewardDistributor is address(this) (constructor). Owner is also address(this).
        address initialDistributor = c.rewardDistributor();
        address owner = c.owner();
        assert(initialDistributor == owner);

        // Actor will attempt to call setRewardDistributor to actor (self); if actor is not owner, the call must fail
        // on the correct contract. We cannot use vm.expectRevert per rules, so we use try/catch to observe success.
        bool ok;
        vm.prank(actor);
        try c.setRewardDistributor(actor) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: if actor is not the owner, the call does not succeed and rewardDistributor remains unchanged.
        // For owner, the call may succeed; so we only assert for non-owner actors.
        if (actor != owner) {
            // actor is non-owner: reference contract should reject and rewardDistributor must still equal owner
            assertTrue(!ok && c.rewardDistributor() == owner);
        } else {
            // actor is owner: reference allows the change; in that case ensure state reflects the change
            // single assertion required by problem: we still must make exactly one assertTrue in total —
            // To satisfy the requirement of exactly one assert, we restructure so above conditional leads to exactly one assertTrue call.
        }
    }
}

