pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// Adversarial token that during safeTransferFrom will call setRewardDistributor on the staking contract
contract MaliciousToken {
    address public target;
    address public attacker;

    constructor(address _target, address _attacker) {
        target = _target;
        attacker = _attacker;
    }

    // ERC20 minimal interfaces used by C: balanceOf, transferFrom, transfer
    function balanceOf(address) external pure returns (uint256) {
        return 0;
    }

    // Called by notifyRewardAmount which does safeTransferFrom from distributor to C
    // We mimic transferFrom by making this call revert or perform side-effects depending on caller
    function transferFrom(address, address, uint256) external returns (bool) {
        // During notifyRewardAmount the staking contract expects this to succeed.
        // Here we call setRewardDistributor on the staking contract as the distributor would do
        // to attempt to change rewardDistributor during the token transfer. This models an
        // ERC20 that triggers a callback (maliciously) allowing the distributor to be changed
        // if the staking contract's setRewardDistributor permissions are wrong (the mutant).
        C(target).setRewardDistributor(attacker);
        return true;
    }

    function transfer(address, uint256) external returns (bool) {
        return true;
    }

    function allowance(address, address) external pure returns (uint256) {
        return type(uint256).max;
    }

    function approve(address, uint256) external pure returns (bool) {
        return true;
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // fuzz: attacker (address) will be used as the new distributor attempted by malicious token during transferFrom
    function testFuzz_property(address attacker) public {
        // keep attacker wide but avoid zero address since setRewardDistributor in reference would still allow owner to set to zero if owner called; we want meaningful address
        if (attacker == address(0)) attacker = address(1);

        // record initial distributor
        address before = c.rewardDistributor();

        // Owner (setUp deployer) adds a reward token; must be called by owner
        // We deploy a malicious token that during transferFrom will call setRewardDistributor(attacker)
        MaliciousToken mal = new MaliciousToken(address(c), attacker);

        // addReward requires rewardData[lastUpdateTime]==0; pass mal address
        // call as owner (this contract) - setUp used address(this) as owner
        c.addReward(address(mal));

        // After addReward completes on reference, rewardDistributor should be unchanged
        // On mutant, during notifyRewardAmount call path (not used by addReward) the distributor could change.
        // However the mutant difference arises because setRewardDistributor permission was changed; to trigger that via an external token
        // we simulate a scenario where notifyRewardAmount would be called by rewardDistributor and token transferFrom invokes setRewardDistributor.
        // So now we act as rewardDistributor and call notifyRewardAmount to move tokens; this will call mal.transferFrom which performs the attack.

        // The test property: after running notifyRewardAmount as the legitimate rewardDistributor, rewardDistributor must remain equal to before.
        // This holds for the reference for all inputs; mutant can be changed by the malicious token's internal setRewardDistributor call.

        // Make sure caller is rewardDistributor
        vm.prank(before);
        // give mal some allowance semantics are mocked inside MaliciousToken
        // call notifyRewardAmount which requires reward token known (we added it) and amount>0
        bool ok;
        try c.notifyRewardAmount(address(mal), 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: for the correct contract, rewardDistributor must remain equal to 'before' after the sequence
        // The mutant (where setRewardDistributor allows the previous rewardDistributor to change it) can make this false for some attacker address
        assertTrue(c.rewardDistributor() == before);
    }
}

