contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzz param: an address that will act as the reward token (we will deploy a malicious token at that address by ignoring it and deploying our own)
    function testFuzz_property(address attackerOwner) public {
        // Keep attackerOwner non-zero to be a valid owner for the token we deploy
        if (attackerOwner == address(0)) attackerOwner = address(1);

        // Deploy a malicious ERC20 that calls back into c during transferFrom
        MaliciousToken token = new MaliciousToken(c, attackerOwner);

        // record pre-state: rewardDistributor should initially be address(this) per setUp
        address before = c.rewardDistributor();

        // The contract owner must call addReward; set up as owner (setUp constructed c with owner = address(this))
        // addReward registers the token; in notifyRewardAmount the contract will call safeTransferFrom which will invoke
        // token.transferFrom -> token._onTransferFrom, which we make call c.setRewardDistributor(...) to attempt to change distributor
        // Call addReward -- this should not change rewardDistributor in the reference implementation
        bool ok;
        try c.addReward(address(token)) {
            ok = true;
        } catch {
            ok = false;
        }
        // exactly one assertion: after addReward, rewardDistributor must equal previous value
        assertTrue(c.rewardDistributor() == before);
    }
