// Minimal malicious token that implements enough of IERC20 for SafeERC20 interactions
contract MaliciousToken {
    C public target;
    address public owner;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => uint256) public balanceOf;

    constructor(C _target, address _owner) {
        target = _target;
        owner = _owner;
        // give some balance to deployer to avoid zero issues if used
        balanceOf[address(this)] = 1e24;
    }

    // minimal ERC20 selector helpers
    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        if (balanceOf[msg.sender] >= amount) {
            balanceOf[msg.sender] -= amount;
            balanceOf[to] += amount;
            return true;
        }
        return false;
